    Bug 1930847 - Fix "Get Selected Messages" with "Leave Messages on Server" disabled. r=kaie


    Do not purge the message database of partial messages that no longer exist on the server when bodies for such messages are downloaded.

    Differential Revision: https://phabricator.services.mozilla.com/D231976

diff --git a/mailnews/local/public/nsIMsgLocalMailFolder.idl b/mailnews/local/public/nsIMsgLocalMailFolder.idl
index 9628be54180..dc12550d400 100644
--- a/mailnews/local/public/nsIMsgLocalMailFolder.idl
+++ b/mailnews/local/public/nsIMsgLocalMailFolder.idl
@@ -113,6 +113,14 @@ interface nsIMsgLocalMailFolder : nsISupports {
    */
   nsIMsgDBHdr retrieveHdrOfPartialMessage(in nsIMsgDBHdr newHdr);

+  /**
+   * This is true while bodies for partial messages are being downloaded. In
+   * this case nsPop3Sink::FindPartialMessages() and CheckPartialMessages()
+   * will not purge the database of partial messages that no longer exist on
+   * the server.
+   */
+  readonly attribute boolean downloadInProgress;
+
   /**
    * Notify about deletion of partial messages not existing anymore on the server.
    *
diff --git a/mailnews/local/src/nsLocalMailFolder.cpp b/mailnews/local/src/nsLocalMailFolder.cpp
index b914c177eff..d16572b8397 100644
--- a/mailnews/local/src/nsLocalMailFolder.cpp
+++ b/mailnews/local/src/nsLocalMailFolder.cpp
@@ -3468,3 +3468,10 @@ NS_IMETHODIMP nsMsgLocalMailFolder::UpdateNewMsgHdr(nsIMsgDBHdr* aOldHdr,

   return NS_OK;
 }
+
+NS_IMETHODIMP
+nsMsgLocalMailFolder::GetDownloadInProgress(bool* downloadInProgress) {
+  NS_ENSURE_ARG_POINTER(downloadInProgress);
+  *downloadInProgress = mDownloadInProgress;
+  return NS_OK;
+}
diff --git a/mailnews/local/src/nsPop3Sink.cpp b/mailnews/local/src/nsPop3Sink.cpp
index b2373954823..caa1546f8ef 100644
--- a/mailnews/local/src/nsPop3Sink.cpp
+++ b/mailnews/local/src/nsPop3Sink.cpp
@@ -66,15 +66,23 @@ partialRecord::~partialRecord() {}
 // matches the current Account, then look for the Uidl and save
 // this message for later processing.
 nsresult nsPop3Sink::FindPartialMessages() {
+  nsCOMPtr<nsIMsgLocalMailFolder> localFolder = do_QueryInterface(m_folder);
+  if (!localFolder) {
+    return NS_ERROR_FAILURE;
+  }
+  bool downloadInProgress = false;
+  localFolder->GetDownloadInProgress(&downloadInProgress);
+  if (downloadInProgress) {
+    return NS_OK;
+  }
+
   nsCOMPtr<nsIMsgEnumerator> messages;
   bool hasMore = false;
   bool isOpen = false;
   nsLocalFolderScanState folderScanState;
   nsCOMPtr<nsIMsgDatabase> db;
-  nsCOMPtr<nsIMsgLocalMailFolder> localFolder = do_QueryInterface(m_folder);
   m_folder->GetMsgDatabase(getter_AddRefs(db));
-  if (!localFolder || !db)
-    return NS_ERROR_FAILURE;  // we need it to grub through the folder
+  if (!db) return NS_ERROR_FAILURE;  // we need it to grub through the folder

   nsresult rv = db->EnumerateMessages(getter_AddRefs(messages));
   if (messages) messages->HasMoreElements(&hasMore);
@@ -121,6 +129,16 @@ nsresult nsPop3Sink::FindPartialMessages() {
 // Any messages that don't exist any more are deleted from the
 // msgDB.
 void nsPop3Sink::CheckPartialMessages(nsIPop3Protocol* protocol) {
+  nsCOMPtr<nsIMsgLocalMailFolder> localFolder = do_QueryInterface(m_folder);
+  if (!localFolder) {
+    return;
+  }
+  bool downloadInProgress = false;
+  localFolder->GetDownloadInProgress(&downloadInProgress);
+  if (downloadInProgress) {
+    return;
+  }
+
   uint32_t count = m_partialMsgsArray.Length();
   bool deleted = false;

@@ -139,8 +157,7 @@ void nsPop3Sink::CheckPartialMessages(nsIPop3Protocol* protocol) {
   }
   m_partialMsgsArray.Clear();
   if (deleted) {
-    nsCOMPtr<nsIMsgLocalMailFolder> localFolder = do_QueryInterface(m_folder);
-    if (localFolder) localFolder->NotifyDelete();
+    localFolder->NotifyDelete();
   }
 }
